command.text:
param([ValidateSet('build','test','build-ck')][string]$Action='build')
$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false)
if(-not [Environment]::MachineName.Equals('baiying',[StringComparison]::OrdinalIgnoreCase)){throw 'Requires baiying'}
$manifest='D:\projects\rz-tree-qk-native-source-r1.json';$m=[IO.File]::ReadAllText($manifest)|ConvertFrom-Json
function Verify-File([string]$Path,[string]$Hash){if((Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToLowerInvariant() -ne $Hash){throw ('Changed input: '+$Path)}}
Verify-File $PSCommandPath $m.script_sha256
$repo=$m.repo.Replace('/','\');$seed=$m.seed.Replace('/','\');$sha=$m.source_commit;$bundle=Join-Path 'D:\projects' $m.bundle
Verify-File $bundle $m.bundle_sha256
if(-not (Test-Path $repo)){
 & git -C $seed fetch $bundle HEAD;if($LASTEXITCODE -ne 0){throw 'Fetch failed'}
 & git -C $seed worktree add --detach $repo $sha;if($LASTEXITCODE -ne 0){throw 'Worktree creation failed'}
}
if((& git -C $repo rev-parse HEAD).Trim() -ne $sha -or @(& git -C $repo status --porcelain).Count -ne 0){throw 'Source mismatch'}
$build=Join-Path $repo 'build\rz-tree-qk';$null=New-Item -ItemType Directory -Path $build -Force
$out=Join-Path $repo ('build\rz-tree-qk-'+$Action+'-r1');$specPath=$out+'.json'
if((Test-Path $out) -or (Test-Path $specPath)){throw 'Evidence exists'}
$files=@(Get-ChildItem (Join-Path $repo 'native') -Recurse -File|Where-Object {$_.Extension -in @('.c','.cpp','.h','.hpp')}|ForEach-Object {$_.FullName})
$files+=@(Join-Path $repo 'tests\native\rz_tree_qk_selftest.cpp')
$files+=@('baiying_build_ck_fmha_q8192.ps1','baiying_guarded_inference.ps1'|ForEach-Object {Join-Path (Join-Path $repo 'scripts') $_})
$inputs=@();foreach($file in ($files|Sort-Object -Unique)){$inputs+=@{file=$file.Substring($repo.Length+1);sha256=(Get-FileHash $file -Algorithm SHA256).Hash.ToLowerInvariant()}}
$spec=[ordered]@{executable='';arguments=@();working_directory=$repo;repo_commit=$sha;command_file=$PSCommandPath;command_file_sha256=$m.script_sha256;source_manifest_sha256=(Get-FileHash $manifest -Algorithm SHA256).Hash.ToLowerInvariant();source_inputs=$inputs;model='none; experimental native FP32 RZ K16 tree QK arithmetic and provider';model_loaded=$false;inference_acceptance=$false;performance_acceptance=$false;purpose='Validate native FP32 round-toward-zero additions against independent specification, actual per-wave mode restoration, original unsupported-dot replay, causal masks and immutable inputs. Original-score differences are diagnostics, not the product acceptance boundary. Build the default-off provider only after native safety passes.';original_qk=$false;additional_workspace_bytes=0;context_capacity=264736}
$env:PATH='C:\Program Files\AMD\ROCm\7.1\bin;'+$env:PATH
$kernel=Join-Path $build 'rz-tree-qk.exe';$building=$Action.StartsWith('build')
if($Action -eq 'build'){
 $selected=$kernel;if(Test-Path $selected){throw 'Binary exists'}
 $link=Join-Path $build 'hipblaslt.lib';Copy-Item 'C:\Program Files\AMD\ROCm\7.1\lib\libhipblaslt.dll.a' $link
 $spec.link_inputs=@(@{file=$link;sha256=(Get-FileHash $link -Algorithm SHA256).Hash.ToLowerInvariant()})
 $spec.executable='C:\Program Files\AMD\ROCm\7.1\bin\hipcc.exe'
 $spec.arguments=@('-std=c++17','-O3','-DQRT_SM121_DPP_REDUCTION=1','-DQRT_SM121_COMPACT_NORMALIZE=1','-DQRT_CK_SM121_INTERPOLATED_EXP2=1','--offload-arch=gfx1151','-L',$build,(Join-Path $repo 'tests\native\rz_tree_qk_selftest.cpp'),'-o',$selected,'-lhipblaslt');$timeout=180
}elseif($Action -eq 'build-ck'){
 $safetyPath=Join-Path $repo 'build\rz-tree-qk-test-r1\run-record.json';$safety=[IO.File]::ReadAllText($safetyPath)|ConvertFrom-Json
 if($safety.reason -ne 'completed' -or $safety.exit_code -ne 0 -or -not $safety.host_checks_pass){throw 'Native safety prerequisite incomplete'}
 $spec.safety_run_sha256=(Get-FileHash $safetyPath -Algorithm SHA256).Hash.ToLowerInvariant()
 $selected=Join-Path $build 'qrt_ck_fmha_sm121.dll';if(Test-Path $selected){throw 'Binary exists'}
 $ck='D:\projects\composable-kernel-fdf4bb7';$headers=@(Get-ChildItem $ck -Recurse -File|Where-Object {$_.Extension -in @('.h','.hpp','.cpp')}|Sort-Object FullName|ForEach-Object {@{file=$_.FullName.Substring($ck.Length+1);bytes=$_.Length;sha256=(Get-FileHash $_.FullName -Algorithm SHA256).Hash.ToLowerInvariant()}})
 $headerPath=Join-Path $build 'ck-source-inputs.json';[IO.File]::WriteAllText($headerPath,($headers|ConvertTo-Json -Depth 5),[Text.UTF8Encoding]::new($false))
 $spec.ck_source_manifest_sha256=(Get-FileHash $headerPath -Algorithm SHA256).Hash.ToLowerInvariant();$spec.ck_source_files=$headers.Count
 $spec.executable='C:\Windows\System32\WindowsPowerShell\v1.0\powershell.exe';$spec.arguments=@('-NoLogo','-NoProfile','-NonInteractive','-File',(Join-Path $repo 'scripts\baiying_build_ck_fmha_q8192.ps1'),'-CkRoot',$ck,'-Sm121InterpolatedExp2','-DppReduction','1','-CompactNormalize','1','-OutPath',$selected,'-HipccPath','C:\Program Files\AMD\ROCm\7.1\bin\hipcc.exe');$timeout=210
}else{
 $metaPath=Join-Path $build 'build-provenance.json';$meta=[IO.File]::ReadAllText($metaPath)|ConvertFrom-Json
 if($meta.repo_commit -ne $sha){throw 'Build commit mismatch'}
 Verify-File $kernel $meta.artifact.sha256
 foreach($file in $meta.source_inputs){Verify-File (Join-Path $repo $file.file) $file.sha256}
 $spec.build_provenance_sha256=(Get-FileHash $metaPath -Algorithm SHA256).Hash.ToLowerInvariant()
 $spec.executable=$kernel;$spec.arguments=@('--selftest');$timeout=240
}
[IO.File]::WriteAllText($specPath,($spec|ConvertTo-Json -Depth 12),[Text.UTF8Encoding]::new($false))
& (Join-Path $repo 'scripts\baiying_guarded_inference.ps1') -SpecPath $specPath -OutDir $out -TimeoutSeconds $timeout|Out-Null
$r=[IO.File]::ReadAllText((Join-Path $out 'run-record.json'))|ConvertFrom-Json
$r|Select-Object reason,exit_code,wall_ms,host_checks|ConvertTo-Json -Depth 5
if($r.reason -ne 'completed' -or $r.exit_code -ne 0 -or -not $r.host_checks_pass){throw 'Native action or host check failed'}
if($building){
 $meta=[ordered]@{host=[Environment]::MachineName;repo_commit=$sha;dirty_tree=$false;sm121_dpp_reduction=$true;sm121_compact_normalize=$true;sm121_interpolated_exp2=$true;source_inputs=$inputs;command_file=$PSCommandPath;command_file_sha256=$m.script_sha256;compiler=$spec.executable;arguments=$spec.arguments;run_record_sha256=(Get-FileHash (Join-Path $out 'run-record.json') -Algorithm SHA256).Hash.ToLowerInvariant();artifact=@{file=$selected;bytes=(Get-Item $selected).Length;sha256=(Get-FileHash $selected -Algorithm SHA256).Hash.ToLowerInvariant()}}
 [IO.File]::WriteAllText((Join-Path $build ($Action+'-provenance.json')),($meta|ConvertTo-Json -Depth 12),[Text.UTF8Encoding]::new($false))
}else{
 $reports=@([IO.File]::ReadAllLines((Join-Path $out 'product.stdout.jsonl'))|Where-Object {$_.StartsWith('{')}|ForEach-Object {$_|ConvertFrom-Json})
 if($reports.Count -ne 25){throw 'Incomplete QK reports'}
 foreach($r in $reports){if($r.spec_bit_mismatches -ne 0 -or $r.mode_errors -ne 0 -or -not $r.redzones_pass -or -not $r.immutable_inputs){throw 'QK arithmetic, mode or memory check failed'}}
}
